%[text] # Getting Started with Rstar in MATLAB
%[text] Estimate the natural rate of interest with the current Laubach-Williams and Holston-Laubach-Williams data published by the Federal Reserve Bank of New York.
%[text] The companion [FRED input-recreation script](http://recreatehlw2023usinputfromfred.m) rebuilds the U.S. core HLW2023 inputs.
%[text:tableOfContents]{"heading":"**Table of Contents**"}
%[text] ## Current U.S. Laubach-Williams estimates
%[text] Download the current U.S. inputs, estimate the COVID-adjusted LW2023 model, and plot the filtered natural rate and trend growth.
%[text] #### Gather the data
lwUrl = "https://www.newyorkfed.org/medialibrary/media/research/economists/williams/data/Laubach_Williams_current_estimates.xlsx";
lwData = readtable(lwUrl, Sheet="input data", VariableNamingRule="preserve");
%[text] #### Estimate the appropriate model
lwModel = rstar("LW2023", rstarOptions("LW2023", Verbose=false));
lwResults = lwModel.estimate(lwData);
lwDates = lwData.Date(9:end);
%[text] #### Plot the results
plot(lwDates, lwResults.stage3.rstarFiltered, LineWidth=2, DisplayName="Natural rate") %[output:027f87e4]
hold on %[output:027f87e4]
plot(lwDates, lwResults.stage3.trendFiltered, LineWidth=2, DisplayName="Trend growth") %[output:027f87e4]
set(gcf, Color="white")
title("Current U.S. Laubach-Williams estimates") %[output:027f87e4]
xlabel("Quarter") %[output:027f87e4]
ylabel("Percent") %[output:027f87e4]
xlim([datetime(1985,1,1), lwDates(end)]) %[output:027f87e4]
ylim([0, 4]) %[output:027f87e4]
grid on %[output:027f87e4]
box on %[output:027f87e4]
legend(Location="southwest") %[output:027f87e4]
%%
%[text] ## Current U.S. Holston-Laubach-Williams estimates
%[text] Estimate HLW2023 with a larger optimization budget for the current U.S. vintage.
%[text] #### Gather the data
hlwUrl = "https://www.newyorkfed.org/medialibrary/media/research/economists/williams/data/Holston_Laubach_Williams_current_estimates.xlsx";
hlwData = readtable(hlwUrl, Sheet="US input data", VariableNamingRule="preserve");
%[text] #### Estimate the model
%[text] In this case, to cater for the more complex model, we adjust the estimation options of the model
optimizer = rstar.utils.maximumLikelihoodOptions(MaxIterations=20000, MaxFunctionEvaluations=50000);
hlwOptions = rstarOptions("HLW2023", OptimizationOptions=optimizer, Verbose=false);
hlwModel = rstar("HLW2023", hlwOptions);
hlwResults = hlwModel.estimate(hlwData);
%%
%[text] #### Plot the results
hlwDates = hlwData.date(5:end);
figure %[output:9ca7bd2c]
plot(hlwDates, hlwResults.stage3.rstarFiltered, LineWidth=2, DisplayName="Natural rate") %[output:9ca7bd2c]

hold on %[output:9ca7bd2c]
plot(hlwDates, hlwResults.stage3.trendFiltered, LineWidth=2, DisplayName="Trend growth") %[output:9ca7bd2c]
set(gcf, Color="white")
title("Current U.S. Holston-Laubach-Williams estimates") %[output:9ca7bd2c]
xlabel("Quarter") %[output:9ca7bd2c]
ylabel("Percent") %[output:9ca7bd2c]
xlim([datetime(1985,1,1), hlwDates(end)]) %[output:9ca7bd2c]
ylim([0, 4]) %[output:9ca7bd2c]
grid on %[output:9ca7bd2c]
box on %[output:9ca7bd2c]
legend(Location="southwest") %[output:9ca7bd2c]
%%
%[text] ## Canada and euro area estimates
%[text] Reuse the HLW2023 settings for Canada. The euro-area specification includes an additional kappa parameter for 2023.
%[text] #### Canada
%[text] In the case of Canada we can simply re-use the same `HLW2023` model that we created before, we only need to re-estimate with the same data
caData = readtable(hlwUrl, Sheet="CA input data", VariableNamingRule="preserve");
hlwModel.Verbose = false;
caResults = hlwModel.estimate(caData);
%%
%[text] #### Euro area
%[text] The Euro Area has some added complexity as we have an additional kappa constraint for 2023.
eaData = readtable(hlwUrl, Sheet="EA input data", VariableNamingRule="preserve");

kappaInputs = rstar.CovidAdjustedOptions.defaultKappaInputs();
kappaInputs(end+1,:) = {"kappa2023", datetime(2023,1,1), datetime(2023,10,1), 1, 1, Inf};
disp(kappaInputs) %[output:62dddbbd]

eaOptions = rstarOptions("HLW2023", KappaInputs=kappaInputs, OptimizationOptions=optimizer, Verbose=false);
eaResults = rstar("HLW2023", eaOptions).estimate(eaData);
%%
%[text] #### Plotting the results
US = timetable(hlwResults.stage3.rstarFiltered, hlwResults.stage3.trendFiltered, hlwResults.stage3.outputGapFiltered, RowTimes=hlwDates, VariableNames=["Natural Rate of Interest", "Trend Growth", "Output Gap"]);
CA = timetable(caResults.stage3.rstarFiltered, caResults.stage3.trendFiltered, caResults.stage3.outputGapFiltered, RowTimes=hlwDates, VariableNames=["Natural Rate of Interest", "Trend Growth", "Output Gap"]);
EA = timetable(eaResults.stage3.rstarFiltered, eaResults.stage3.trendFiltered, eaResults.stage3.outputGapFiltered, RowTimes=eaData.date(5:end), VariableNames=["Natural Rate of Interest", "Trend Growth", "Output Gap"]);

figure(Visible = 'on', Color = 'w') %[output:428c461e]
ax = stackedplot(US, CA, EA, LegendLabels=["United States", "Canada", "Euro Area"], LineWidth = 2); %[output:428c461e]
grid on
ax.AxesProperties(1).YLimits = [0, 8]; %[output:428c461e]
ax.AxesProperties(2).YLimits = [0, 6]; %[output:428c461e]
ax.AxesProperties(3).YLimits = [-10, 10]; %[output:428c461e]

